import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.BTt0kA_k.js";const o="/RelayPulse/screenshots/user/settings-general.webp",_=JSON.parse('{"title":"通用设置","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/settings.md","filePath":"user/use/settings.md"}'),i={name:"user/use/settings.md"};function n(d,e,l,h,p,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="通用设置" tabindex="-1">通用设置 <a class="header-anchor" href="#通用设置" aria-label="Permalink to &quot;通用设置&quot;">​</a></h1><p>入口：<strong>配置 → 通用设置</strong>。本页开关和选择项会在操作后保存；保存失败会显示错误，界面以保存成功的值为准。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/settings-general.webp"><img src="'+o+'" alt="通用设置中的启动、后台运行、状态栏图标、主题语言和数据设置"></a></p><figcaption>① 启动与后台运行开关；② 主题和语言。下面可设置记录保留时间、查看日志并导出诊断包。</figcaption></figure><h2 id="启动与后台" tabindex="-1">启动与后台 <a class="header-anchor" href="#启动与后台" aria-label="Permalink to &quot;启动与后台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td>开机自动启动</td><td>登录系统后自动启动 RelayPulse</td></tr><tr><td>关闭主窗口后继续运行</td><td>控制关闭主窗口后的后台运行，同时是自动周期探测的总开关</td></tr><tr><td>显示状态栏图标</td><td>控制 macOS 状态栏图标的显示</td></tr></tbody></table><p>“关闭主窗口后继续运行”关闭时，即使主窗口仍打开，也不会继续派发新的自动探测。已经发出的请求会正常结束；手动探测由你显式触发。</p><p>隐藏状态栏图标不会自动关闭后台探测。如果只想暂停自动探测，应关闭后台开关，或停用相应站点、模型。</p><h2 id="外观与语言" tabindex="-1">外观与语言 <a class="header-anchor" href="#外观与语言" aria-label="Permalink to &quot;外观与语言&quot;">​</a></h2><p>主题可选“跟随系统”“浅色”“深色”，小面板会同步应用主题。</p><p>当前界面语言提供“简体中文”。页面只提供这一选项时，不能切换为其他语言。</p><h2 id="探测记录保留时间" tabindex="-1">探测记录保留时间 <a class="header-anchor" href="#探测记录保留时间" aria-label="Permalink to &quot;探测记录保留时间&quot;">​</a></h2><p>当前页面提供“保留 30 天”。过期正式探测记录会自动清理，站点和模型配置不受影响。对应请求缓存和 Token 统计也会随记录清理调整。</p><p>手动清理的范围见<a href="./records.html#删除与清理">探测记录</a>。IQ 测试历史在其历史列表中单独管理。</p><h2 id="诊断日志" tabindex="-1">诊断日志 <a class="header-anchor" href="#诊断日志" aria-label="Permalink to &quot;诊断日志&quot;">​</a></h2><p>“诊断日志”显示当前日志文件数和总大小。点击“打开日志目录”在文件管理器中查看；点击清理图标并确认，会删除本地诊断日志，不会删除站点配置或正式探测记录。</p><h2 id="导出诊断包" tabindex="-1">导出诊断包 <a class="header-anchor" href="#导出诊断包" aria-label="Permalink to &quot;导出诊断包&quot;">​</a></h2><p>点击“导出诊断包”，按界面提示找到生成的文件，用于向项目反馈问题。诊断包包含错误链路、失败探测摘要和日志容量信息，不包含正式请求响应正文。</p><p>如需定位某次请求的具体响应，进入“运行 → 探测记录”打开详情。反馈问题时说明应用版本、发生时间、执行的操作及错误提示，便于关联日志。</p>',18)])])}const f=t(i,[["render",n]]);export{_ as __pageData,f as default};
